// ---------------------------------------------------------------------
// WF-14: Master Agent — intent classification + specialist routing.
// 1. identify event  2. identify user/lead  3. determine intent
// 4. select specialist agent  5. flag approval-gated actions
// 6. human-handoff triggers
// ---------------------------------------------------------------------
// Deterministic routing (no LLM required). Add LLM classification when
// GEMINI_API_KEY is set for genuinely ambiguous inputs.

const item = $input.first().json;
const event = item.event || {};
const type = String(item.type || event.type || '').toLowerCase();
const src = String(item.source || event.source || '').toLowerCase();
const text = String(item.message || event.message || item.question || '').toLowerCase();

let agent = 'default';

if (type.includes('lead') || src === 'website' || src === 'book-consultation' || type.includes('enquiry')) {
  agent = 'lead';
} else if (type.includes('whatsapp') || src === 'whatsapp') {
  agent = 'whatsapp';
} else if (type.includes('content') || type.includes('idea') || type.includes('script')) {
  agent = 'content';
} else if (type.includes('publish') || type.includes('youtube') || type.includes('instagram') || type.includes('facebook') || type.includes('reel')) {
  agent = 'social_publish';
} else if (type.includes('report') || type.includes('analytics')) {
  agent = 'analytics';
} else if (type.includes('seo') || type.includes('audit')) {
  agent = 'seo';
} else if (type.includes('error') || type.includes('retry')) {
  agent = 'error';
}

// Human hand-off triggers (always override)
const handoff = ['complaint', 'refund', 'legal', 'lawyer', 'regulatory', 'angry', 'payment issue',
  'human', 'agent', 'speak to a person', 'talk to someone'];
if (handoff.some((k) => text.includes(k))) agent = 'human_handoff';

// Irreversible / high-impact actions => require human approval (route to WF-15)
const destructiveKeywords = ['bulk', 'delete', 'publish', 'send_mass', 'change_settings', 'spend'];
const isDestructive = destructiveKeywords.some((k) => type.includes(k) || text.includes(k));
const needsApproval = isDestructive || agent === 'social_publish';

return [{
  json: {
    ...item,
    __routing: {
      agent,
      needs_approval: needsApproval,
      requires_human: agent === 'human_handoff',
      decision_reason: 'deterministic route',
      ts: new Date().toISOString(),
    },
  },
}];

// ---------------------------------------------------------------------
// Dispatch stub. TODO (BLOCKED on n8n workflow IDs):
//  - Replace with an n8n 'Execute Workflow' node per specialist agent.
//  - Route on $json.__routing.agent: lead->WF-01, whatsapp->WF-05/06,
//    content->WF-07, social_publish->WF-15 (approval gate), analytics->WF-12,
//    seo->WF-11, error->WF-13, human_handoff->notify human.
//  - Persist an AutomationLogs row (workflow_name, execution_id, event_type,
//    status, result) before returning.
// ---------------------------------------------------------------------
const item = $input.first().json;

const r = item.__routing;
const actionMap = {
  lead: 'WF-01 Website Lead Intake',
  whatsapp: 'WF-05/06 WhatsApp',
  content: 'WF-07 Content Generation',
  social_publish: 'WF-15 Human Approval Queue (gated)',
  analytics: 'WF-12 Analytics',
  seo: 'WF-11 SEO Audit',
  error: 'WF-13 Error Monitoring',
  human_handoff: 'HUMAN_HANDOFF — notify staff',
  default: 'UNROUTED — queue for review',
};

return [{
  json: {
    ...item,
    __dispatch: {
      target_workflow: actionMap[r.agent] || actionMap.default,
      needs_approval: r.needs_approval,
      requires_human: r.requires_human,
      note: 'Scaffold: wire Execute Workflow nodes + AutomationLogs write to complete.',
    },
  },
}];
